// Generated by vibelang from src/providers/models/search.ts; the migrate flow writes it again with each batch.
const normalizeModelSearch = (value) => value
    .toLowerCase()
    .replace(/[^\p{Letter}\p{Number}]+/gu, " ")
    .trim()
    .replace(/\s+/g, " ");
const compactModelSearch = (value) => normalizeModelSearch(value).replaceAll(" ", "");
export const matchesModelSearch = (query, values) => {
    const search = normalizeModelSearch(query);
    if (!search)
        return true;
    const compactSearch = compactModelSearch(query);
    return values.some((value) => normalizeModelSearch(value).includes(search) || compactModelSearch(value).includes(compactSearch));
};
